import Replicate from 'replicate';

const replicate = new Replicate({
  auth: process.env.REPLICATE_API_TOKEN!,
});

// Run FLUX Schnell (fast, good quality)
const output = await replicate.run(
  'black-forest-labs/flux-schnell',
  {
    input: {
      prompt: 'A serene Japanese garden with cherry blossoms, golden hour, photorealistic',
      num_outputs: 1,
      aspect_ratio: '16:9',
      output_format: 'webp',
      output_quality: 90,
    },
  }
) as string[];

const imageUrl = output[0];
console.log('Generated image:', imageUrl);

// For streaming output (e.g., LLM text generation)
for await (const event of replicate.stream('meta/meta-llama-3-8b-instruct', {
  input: { prompt: 'Write a haiku about code reviews.' },
})) {
  process.stdout.write(String(event));
}
